{
  "name": "oh-my-resume",
  "version": "0.2.0",
  "description": "AI-Powered Interview Preparation Agent System for OpenCode",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "bin": {
    "oh-my-resume": "./dist/cli.js"
  },
  "scripts": {
    "build": "tsc && chmod +x dist/cli.js",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run clean && npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ai",
    "agent",
    "interview",
    "resume",
    "career"
  ],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.12"
  },
  "devDependencies": {
    "@types/bun": "^1.0.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist",
    "assets",
    "README.md"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/goalSetter09/oh-my-resume"
  },
  "engines": {
    "node": ">=18"
  }
}
